		public virtual string DadosCompletosToText
		{
			get
			{
				List<string> list = new List<string>();
				if (!string.IsNullOrWhiteSpace(Defeito))
				{
					list.Add($"Defeito/Serviço solicitado: {Defeito}");
				}
				if (!string.IsNullOrWhiteSpace(Diagnostico))
				{
					list.Add($"Diagnóstico: {Diagnostico}");
				}
				if (!DataGarantia.Equals(DateTime.MinValue))
				{
					list.Add($"Data garantia: {DataGarantia.Date.FormatarData()}");
				}
				if (!string.IsNullOrWhiteSpace(Objeto.Marca))
				{
					list.Add($"Marca: {Objeto.Marca}");
				}
				if (!string.IsNullOrWhiteSpace(Objeto.Modelo))
				{
					list.Add($"Modelo: {Objeto.Modelo}");
				}
				if (!string.IsNullOrWhiteSpace(Objeto.Placa))
				{
					list.Add($"Placa: {Objeto.Placa}");
				}
				if (!string.IsNullOrWhiteSpace(Objeto.Serial))
				{
					list.Add($"Serial: {Objeto.Serial}");
				}
				if (!string.IsNullOrWhiteSpace(Objeto.Renavam))
				{
					list.Add($"Renavam: {Objeto.Renavam}");
				}
				if (!string.IsNullOrWhiteSpace(Objeto.Chassi))
				{
					list.Add($"Chassi: {Objeto.Chassi}");
				}
				if (!string.IsNullOrWhiteSpace(Objeto.Cor))
				{
					list.Add($"Cor: {Objeto.Cor}");
				}
				if (Objeto.AnoFabricacao > 0)
				{
					list.Add($"Ano de fabricação: {Objeto.AnoFabricacao}");
				}
				if (!string.IsNullOrWhiteSpace(Objeto.Cilindrada))
				{
					list.Add($"Cilindrada: {Objeto.Cilindrada}");
				}
				if (!string.IsNullOrWhiteSpace(Objeto.Potencia))
				{
					list.Add($"Potência: {Objeto.Potencia}");
				}
				if (!string.IsNullOrWhiteSpace(Objeto.Motor))
				{
					list.Add($"Motor: {Objeto.Motor}");
				}
				if (!string.IsNullOrWhiteSpace(Objeto.Segmento))
				{
					list.Add($"Segmento: {Objeto.Segmento}");
				}
				list.AddRange(from x in Objeto.Personalizado.Campos
					where x.ExibirImpressao
					select x into campoPersonalizadoDto
					select $"{campoPersonalizadoDto.TipoPersonalizado.Descricao}: {campoPersonalizadoDto.ValorParaImpressao}");
				list.AddRange(from x in Personalizado.Campos
					where x.ExibirImpressao
					select x into campoPersonalizadoDto
					select $"{campoPersonalizadoDto.TipoPersonalizado.Descricao}: {campoPersonalizadoDto.ValorParaImpressao}");
				return list.ToArray().LinhasParaTextoComEspacamento() ?? throw new InvalidOperationException("[NullGuard] Return value of property 'System.String DigisatServer.Application.Main.Dto.Movimentacoes.MovimentacaoObjetoDto::DadosCompletosToText()' is null.");
