		public bool Dav
		{
			get
			{
				if (TipoMovimentacao != TipoMovimentacao.Dav && TipoMovimentacao != TipoMovimentacao.DavOs && TipoMovimentacao != TipoMovimentacao.Orcamento)
				{
					return TipoMovimentacao == TipoMovimentacao.Delivery;
				}
				return true;
			}
		}

		public bool IsDocumentoAuxiliar
		{
			get
			{
				if (TipoMovimentacao != TipoMovimentacao.PreVenda && TipoMovimentacao != TipoMovimentacao.PedidoCompra)
				{
					return Dav;
				}
				return true;
			}
		}

		public bool Saida
		{
			get
			{
				if (!Dav && TipoMovimentacao != TipoMovimentacao.PreVenda && TipoMovimentacao != TipoMovimentacao.CupomFiscal && TipoMovimentacao != TipoMovimentacao.NotaFiscalServico && TipoMovimentacao != TipoMovimentacao.NotaManual && TipoMovimentacao != TipoMovimentacao.CupomFiscalEletronico && TipoMovimentacao != TipoMovimentacao.NotaFiscalConsumidorEletronica)
				{
					return TipoMovimentacao == TipoMovimentacao.NotaFiscalEletronicaSaida;
				}
				return true;
			}
		}

		private string DetalhesItem
		{
			get
			{
				string text = $"Código interno: {ProdutoServico.CodigoInterno}\n" + $"Descrição: {ProdutoServico.Descricao}\n" + $"CST: {Percentual?.ToText}\n" + $"CFOP: {OperacaoFiscal?.Cfop?.Codigo}\n" + $"Preço unitário: {PrecoUnitario:0.00########}\n" + $"Total Bruto: {TotalBruto:0.00##}\n" + $"Desconto aplicado: {TotalDesconto:0.00##}\n" + $"Frete: {Frete:0.00##}\n" + $"Seguro: {Seguro:0.00##}\n" + $"Outras despesas: {OutrasDespesasDigitado + OutrasDespesasProporcional:0.00##}";
				if (!string.IsNullOrEmpty(Estoque.InformacoesEstoqueRelatorio))
				{
					text += $"\nEstoque vendido: {Estoque.InformacoesEstoqueRelatorio}";
				}
				if (!MovimentacaoObjeto.Is<MovimentacaoObjetoDtoNull>())
				{
					text += $"\nObjeto: {MovimentacaoObjeto.Objeto.Descricao}";
				}
				return text;
			}
		}

