				}
				if (!string.IsNullOrEmpty(descricao))
				{
					return $"{ProdutoServico.Descricao} {descricao}  {codigoBarras}" ?? throw new InvalidOperationException("[NullGuard] Return value of property 'System.String DigisatServer.Application.Main.Dto.Movimentacoes.ItemDto::ToCodigoDescricao()' is null.");
				}
