		public string InformacoesImpostoToText
		{
			get
			{
				string text = string.Empty;
				if (Ipi.IsNotNull() && Ipi.Valor > 0m)
				{
					text += $"IPI: R$ {Ipi.Valor} ({Ipi.Percentual}%) ";
				}
				if (Percentual.IsNotNull() && Percentual.ValorSt > 0m)
				{
					text += $"ICMS ST: R$ {Percentual.ValorSt} ";
				}
				if (Percentual.IsNotNull() && Percentual.ValorFundoCombatePobrezaStInterno != 0m)
				{
					text += $"FCP ST: R$ {Percentual.ValorFundoCombatePobrezaStInterno} ";
				}
				return text ?? throw new InvalidOperationException("[NullGuard] Return value of property 'System.String DigisatServer.Application.Main.Dto.Movimentacoes.ItemDto::InformacoesImpostoToText()' is null.");
			}
		}
