		public virtual bool Saida
		{
			get
			{
				if (Tipo != TipoMovimentacao.Delivery && Tipo != TipoMovimentacao.Dav && Tipo != TipoMovimentacao.DavOs && Tipo != TipoMovimentacao.Orcamento && Tipo != TipoMovimentacao.PreVenda && Tipo != TipoMovimentacao.CupomFiscal && Tipo != TipoMovimentacao.NotaFiscalServico && Tipo != TipoMovimentacao.NotaManual && Tipo != TipoMovimentacao.CupomFiscalEletronico && Tipo != TipoMovimentacao.NotaFiscalConsumidorEletronica)
				{
					return Tipo == TipoMovimentacao.NotaFiscalEletronicaSaida;
				}
				return true;
			}
		}

		public virtual bool SaidaConsumidorFinal
		{
			get
			{
				if (Tipo != TipoMovimentacao.PreVenda && Tipo != TipoMovimentacao.CupomFiscal && Tipo != TipoMovimentacao.NotaManual)
				{
					return Tipo == TipoMovimentacao.NotaFiscalConsumidorEletronica;
				}
				return true;
			}
		}

