		public ItemMovimentadoDto ProcessarEstoque()
		{
			foreach (EstoqueDto item in Estoque)
			{
				if (item is EstoqueSerialDto)
				{
					Seriais.AddRange(ObterSeriais(item as EstoqueSerialDto));
				}
				if (item is EstoqueGradeDto)
				{
					Grades.AddRange(ObterGrades(item as EstoqueGradeDto));
				}
				if (item is EstoqueLoteDto)
				{
					Lotes.AddRange(ObterLotes(item as EstoqueLoteDto));
				}
			}
			return this ?? throw new InvalidOperationException("[NullGuard] Return value of method 'DigisatServer.Application.Main.Dto.Movimentacoes.Relatorios.ItemMovimentadoDto DigisatServer.Application.Main.Dto.Movimentacoes.Relatorios.ItemMovimentadoDto::ProcessarEstoque()' is null.");
		}

		private IEnumerable<ItemMovimentadoSerialDto> ObterSeriais(EstoqueSerialDto dtoSerial)
		{
			if (!dtoSerial.IsNull())
			{
				return dtoSerial.Seriais.Select((SerialDto s) => new ItemMovimentadoSerialDto
				{
					Serial = s.Codigo
				}).ToListEmptyWhenNull();
			}
			return Enumerable.Empty<ItemMovimentadoSerialDto>();
		}

		private IEnumerable<ItemMovimentadoGradeDto> ObterGrades(EstoqueGradeDto dtoGrade)
		{
			if (!dtoGrade.IsNull())
			{
				return dtoGrade.Grades.Where((DigisatServer.Application.Main.Dto.Cadastros.ProdutosServicos.GradeDto g) => g.Estoque.Quantidade > 0m).Select(ObterGrade).ToList();
			}
			return Enumerable.Empty<ItemMovimentadoGradeDto>();
		}

		private IEnumerable<ItemMovimentadoLoteDto> ObterLotes(EstoqueLoteDto dtoLote)
		{
			if (!dtoLote.IsNull())
			{
				return dtoLote.Lotes.Where((LoteDto l) => l.Estoque.Quantidade > 0m).Select(ObterLote);
			}
			return Enumerable.Empty<ItemMovimentadoLoteDto>();
		}

		private ItemMovimentadoGradeDto ObterGrade(DigisatServer.Application.Main.Dto.Cadastros.ProdutosServicos.GradeDto dtoGrade)
		{
			EstoqueSerialDto dtoSerial = dtoGrade.Estoque as EstoqueSerialDto;
			return new ItemMovimentadoGradeDto
			{
				Linha = dtoGrade.Linha.Descricao,
				Coluna = dtoGrade.Coluna.Descricao,
				Quantidade = dtoGrade.Estoque.Quantidade,
				Seriais = ObterSeriais(dtoSerial)
			};
		}

		private ItemMovimentadoLoteDto ObterLote(LoteDto dtoLote)
		{
			return new ItemMovimentadoLoteDto
			{
				Quantidade = dtoLote.Estoque.Quantidade,
				Lote = dtoLote.Numero,
				Validade = dtoLote.DataValidade,
				Seriais = ObterSeriais(dtoLote.Estoque as EstoqueSerialDto),
